func (s *Store) load(checkpointID id.CheckpointID) (*storedCheckpoint, error) {
	data, err := os.ReadFile(s.path(checkpointID))
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // absent checkpoint, not an error
		}
		return nil, fmt.Errorf("fsstore: read %s: %w", checkpointID, err)
	}
	var sc storedCheckpoint
	if err := json.Unmarshal(data, &sc); err != nil {
		return nil, fmt.Errorf("fsstore: parse %s: %w", checkpointID, err)
	}
	return &sc, nil
}

func (c *redactCache) load(treePath string) *redactPrefixEntry {
	data, err := osroot.ReadFileNoFollow(c.root, c.entryName(treePath))
	if err != nil {
		return nil
	}
	var entry redactPrefixEntry
	if err := json.Unmarshal(data, &entry); err != nil {
		return nil
	}
	if entry.SourceBytes <= 0 || entry.SourceHash == "" {
		return nil
	}
	if entry.RedactedBlob == "" && entry.RedactedFile == "" {
		return nil
	}
	return &entry
}
